'use client';

import * as React from 'react';
import { cn } from '@/lib/utils';

export type RadioProps = Omit<React.InputHTMLAttributes<HTMLInputElement>, 'type'> & {
  /** Controlled checked state; omit for uncontrolled usage. */
  checked?: boolean;
  /** Fired when the user selects this radio. */
  onCheckedChange?: (checked: boolean) => void;
};

/**
 * Accessible radio built on the native input, to be used inside a
 * `RadioGroup` (which provides the shared `name`). Platform keyboard
 * navigation and form semantics come for free.
 */
const Radio = React.forwardRef<HTMLInputElement, RadioProps>(
  ({ className, checked, onCheckedChange, onChange, ...props }, ref) => (
    <input
      type="radio"
      ref={ref}
      checked={checked}
      onChange={(event) => {
        onCheckedChange?.(event.target.checked);
        onChange?.(event);
      }}
      className={cn(
        'h-4 w-4 shrink-0 rounded-full border border-primary',
        'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background',
        'disabled:cursor-not-allowed disabled:opacity-50',
        'checked:bg-primary checked:text-primary-foreground',
        className
      )}
      {...props}
    />
  )
);
Radio.displayName = 'Radio';

export type RadioGroupProps = {
  /** Shared name applied to every radio in the group. */
  name: string;
  /** Accessible group label; rendered as <legend> inside a fieldset. */
  legend?: string;
  /** Currently selected value (controlled). */
  value?: string;
  /** Initial value (uncontrolled). */
  defaultValue?: string;
  /** Called with the newly selected value. */
  onValueChange?: (value: string) => void;
  /** Stack options (default) or lay them out in a wrapping row. */
  orientation?: 'vertical' | 'horizontal';
  /** Group-level validation message; announced via role=alert. */
  error?: string;
  className?: string;
  children: React.ReactNode;
};

/**
 * Groups related radios with a shared name and accessible legend.
 * Renders a native <fieldset>/<legend> so screen readers announce the
 * group context alongside each option.
 */
const RadioGroup = React.forwardRef<HTMLFieldSetElement, RadioGroupProps>(
  ({ name, legend, value, defaultValue, onValueChange, orientation = 'vertical', error, className, children }, ref) => {
    const [internalValue, setInternalValue] = React.useState(defaultValue ?? '');
    const currentValue = value ?? internalValue;

    const handleChange = (next: string) => {
      if (value === undefined) setInternalValue(next);
      onValueChange?.(next);
    };

    return (
      <fieldset
        ref={ref}
        className={cn(
          orientation === 'vertical' ? 'space-y-2' : 'flex flex-row flex-wrap gap-x-4 gap-y-2',
          className
        )}
      >
        {legend && <legend className="text-sm font-medium">{legend}</legend>}
        <RadioGroupContext.Provider value={{ name, value: currentValue, onChange: handleChange }}>
          {children}
        </RadioGroupContext.Provider>
        {error && (
          <p role="alert" className="text-xs text-destructive">
            {error}
          </p>
        )}
      </fieldset>
    );
  }
);
RadioGroup.displayName = 'RadioGroup';

type RadioGroupContextValue = {
  name: string;
  value: string;
  onChange: (value: string) => void;
};

/** Shared group state — exported so custom option controls (RadioCard) can join a RadioGroup. */
export const RadioGroupContext = React.createContext<RadioGroupContextValue>({
  name: '',
  value: '',
  onChange: () => {},
});

export type RadioGroupItemProps = Omit<RadioProps, 'name' | 'checked' | 'onCheckedChange' | 'value'> & {
  /** The value this item contributes to the group. */
  value: string;
  /** Visible label rendered next to the radio. */
  label?: string;
};

/** A single radio option inside a `RadioGroup`. */
const RadioGroupItem = React.forwardRef<HTMLInputElement, RadioGroupItemProps>(
  ({ value, label, className, id, ...props }, ref) => {
    const group = React.useContext(RadioGroupContext);
    const generatedId = React.useId();
    const inputId = id ?? generatedId;

    return (
      <div className="flex items-center gap-2">
        <Radio
          ref={ref}
          id={inputId}
          name={group.name}
          value={value}
          checked={group.value === value}
          onCheckedChange={(checked) => checked && group.onChange(value)}
          className={className}
          {...props}
        />
        {label && (
          <label htmlFor={inputId} className="text-sm leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70">
            {label}
          </label>
        )}
      </div>
    );
  }
);
RadioGroupItem.displayName = 'RadioGroupItem';

export { Radio, RadioGroup, RadioGroupItem };

'use client';

import * as React from 'react';
import { Radio, RadioGroupContext } from './Radio';
import { cn } from '@/lib/utils';

export type RadioCardProps = {
  /** The value this section contributes to the group. */
  value: string;
  /** Section heading. */
  title?: string;
  /** Supporting line under the title. */
  description?: string;
  /** Custom body rendered after title/description. */
  children?: React.ReactNode;
  /** Outer border radius on the section (default true). */
  rounded?: boolean;
  disabled?: boolean;
  className?: string;
  id?: string;
};

/**
 * A whole section as one radio option: the entire card is the label,
 * the native radio circle is visually hidden (kept for semantics and
 * keyboard use), and selection shows as a primary border + tint via
 * has-[:checked]. Meant to sit inside a `RadioGroup`.
 */
const RadioCard = React.forwardRef<HTMLLabelElement, RadioCardProps>(
  ({ value, title, description, children, rounded = true, disabled, className, id }, ref) => {
    const group = React.useContext(RadioGroupContext);
    const generatedId = React.useId();
    const inputId = id ?? generatedId;

    return (
      <label
        ref={ref}
        htmlFor={inputId}
        className={cn(
          'flex cursor-pointer flex-col gap-1.5 border border-border p-4 transition-colors',
          rounded ? 'rounded-lg' : 'rounded-none',
          'hover:border-muted-foreground/40 hover:bg-muted/30',
          // Selected state rides on the hidden input — no visible circle.
          'has-[:checked]:border-primary has-[:checked]:bg-primary/5',
          'has-[:focus-visible]:ring-2 has-[:focus-visible]:ring-ring has-[:focus-visible]:ring-offset-2 has-[:focus-visible]:ring-offset-background',
          disabled && 'cursor-not-allowed opacity-50 hover:border-border hover:bg-transparent',
          className
        )}
      >
        <Radio
          id={inputId}
          value={value}
          checked={group.value === value}
          onCheckedChange={(checked) => checked && group.onChange(value)}
          disabled={disabled}
          className="sr-only"
        />
        {title && <span className="text-sm font-medium leading-none">{title}</span>}
        {description && <span className="text-sm text-muted-foreground">{description}</span>}
        {children}
      </label>
    );
  }
);
RadioCard.displayName = 'RadioCard';

export { RadioCard };

